custom_css:
/* ════════════════════════════════════════
   十二时辰 · 寅 · 永眠
   寅时 03:00—05:00 ｜ 低温宇宙
   by if love
   ────────────────────────────────────────
   可调变量都在下面 :root 的「可调」段里
   ════════════════════════════════════════ */
@import url('https://fonts.googleapis.com/css2?family=IM+Fell+English:ital@0;1&family=Noto+Serif+SC:wght@400;500&family=DotGothic16&family=Zhi+Mang+Xing&display=swap');

:root{
  /* —— 可调 —— */
  --yy-dz-state: running;        /* 头像消散：running 循环 / paused 关闭（停在完整的样子） */
  --yy-dz-speed: 14s;            /* 一轮消散+重组的时长 */
  --yy-vitals: "体温 −196℃\A心率 3 / min\A休眠舱 · 寅-03";   /* 角色名下的三行小字 */
  --yy-sign: "—— 未完待醒";      /* 每楼结尾落款 */
  --yy-brush: "永眠";            /* 角色头像旁的竖排大字 */
  --yy-banner-show: .45;         /* 楼层顶部星云的浓度，0 关闭 */

  /* —— 颜色与字体 —— */
  --yy-am: #d9a35a;
  --yy-ink: #c9c7c1;
  --yy-pale: #e9e5da;
  --yy-dim: #7a7c83;
  --yy-plate: rgba(14,15,18,.88);
  --yy-well: #08090b;
  --yy-serif: "Noto Serif SC", "Source Han Serif SC", "Songti SC", serif;
  --yy-brushf: "Zhi Mang Xing", "STXingkai", cursive;
  --yy-fell: "IM Fell English", Georgia, serif;
  --yy-dot: "DotGothic16", ui-monospace, monospace;
  --mainFontFamily: var(--yy-serif);
  --yy-plate-shadow: inset 0 1px 0 rgba(255,255,255,.06), inset 0 -1px 0 rgba(0,0,0,.9);
  --yy-vignette: radial-gradient(ellipse 120% 100% at 50% 50%,transparent 60%,rgba(0,0,0,.55));

  /* —— 素材 —— */
  --yy-send: url("data:image/png;base64,");
  --yy-moon-on: url("data:image/png;base64,");
  --yy-lily: url("data:image/webp;base64,");
  --yy-frame: url("data:image/webp;base64,");
  --yy-nebula: url("data:image/webp;base64,");
  --yy-i-moon: url("data:image/webp;base64,");
  --yy-i-pod: url("data:image/webp;base64,");
  --yy-i-snow: url("data:image/webp;base64,");
  --yy-i-star: url("data:image/webp;base64,");
  --yy-i-quill: url("data:image/webp;base64,");
  --yy-i-puzzle: url("data:image/webp;base64,");
  --yy-ramp: url("data:image/png;base64,");
  --yy-fine: url("data:image/png;base64,");
  --yy-coarse: url("data:image/png;base64,");
  --yy-edge: url("data:image/png;base64,");
  --yy-frost: url("data:image/png;base64,");
  --yy-grain: url("data:image/png;base64,");
}

/* ═══ 滚动条全部隐藏 ═══ */
*{scrollbar-width:none}
*::-webkit-scrollbar{width:0;height:0;display:none}

body{font-family:var(--yy-serif)}

/* ═══ 顶栏 ═══ */
#top-bar{background:linear-gradient(rgba(0,0,0,.9),rgba(0,0,0,.35));box-shadow:none;border:0;backdrop-filter:none}
#top-settings-holder .drawer-icon{width:30px;height:30px;color:transparent;background:center/22px 22px no-repeat;opacity:.7;position:relative;transition:opacity .3s}
#top-settings-holder .drawer-icon::before{content:""}
#top-settings-holder .drawer-icon:hover{opacity:.95}
#top-settings-holder .drawer-icon.openIcon{opacity:1}
#top-settings-holder .drawer-icon.openIcon::after{content:"";position:absolute;left:50%;bottom:-5px;width:4px;height:4px;margin-left:-2px;border-radius:50%;background:var(--yy-am)}
#ai-config-button .drawer-icon{background-image:var(--yy-i-snow)}
#sys-settings-button .drawer-icon{background-image:var(--yy-i-star)}
#advanced-formatting-button .drawer-icon{background-image:var(--yy-i-quill)}
#WI-SP-button .drawer-icon{background-image:var(--yy-i-moon)}
#user-settings-button .drawer-icon{background-image:var(--yy-i-snow);transform:rotate(30deg)}
#backgrounds-button .drawer-icon{background-image:var(--yy-i-moon);transform:scaleX(-1)}
#extensions-settings-button .drawer-icon{background-image:var(--yy-i-puzzle)}
#persona-management-button .drawer-icon{background-image:var(--yy-i-star);transform:rotate(45deg)}
#rightNavHolder .drawer-icon{background-image:var(--yy-i-pod)}

/* ═══ 抽屉面板 ═══ */
.drawer-content{background-color:#0b0c0e;background-image:var(--yy-vignette),var(--yy-grain);border:0;border-radius:0;box-shadow:var(--yy-plate-shadow)}

/* ═══ 聊天区 ═══ */
#chat{overflow-x:hidden}
#chat .mes{position:relative;max-width:100%;min-width:0;margin:16px 0;border:0;border-radius:0;overflow-x:clip;
  background-color:var(--yy-plate);background-image:var(--yy-vignette),var(--yy-grain);box-shadow:var(--yy-plate-shadow)}
#chat .mes .mes_block{position:static;min-width:0;box-sizing:border-box;width:auto;max-width:100%}
#chat .mes .mes_text{font-family:var(--yy-serif);font-size:calc(var(--mainFontSize) * 1.02);line-height:2;color:var(--yy-ink);
  max-width:100%;overflow-wrap:anywhere;word-break:break-word}
#chat .mes .mes_text *{max-width:100%;box-sizing:border-box}
#chat .mes .mes_text pre,#chat .mes .mes_text code{white-space:pre-wrap;word-break:break-word}
#chat .mes .mes_text details,#chat .mes .mes_text summary{white-space:normal;overflow-wrap:anywhere}
#chat .mes .mes_text table{display:block;overflow-x:auto}
#chat .mes .mes_text img{height:auto}
#chat .mes .mes_text q{color:var(--yy-am)}
#chat .mes .mes_text em,#chat .mes .mes_text i{color:#9a9ca3}

/* —— 角色楼：休眠舱 —— */
#chat .mes:not([is_user="true"]){display:block;padding:0 0 4px}
#chat .mes:not([is_user="true"])::before{content:"";position:absolute;left:0;right:0;top:0;height:150px;pointer-events:none;
  background:var(--yy-nebula) 40% 0/170% auto no-repeat;opacity:var(--yy-banner-show);
  -webkit-mask:linear-gradient(#000 30%,transparent);mask:linear-gradient(#000 30%,transparent)}
#chat .mes:not([is_user="true"]) .mesAvatarWrapper{position:relative;left:16px;top:0;margin:44px 0 0;width:150px;height:150px;padding:0;z-index:3}
#chat .mes:not([is_user="true"]) .mes_block{padding:58px 18px 0}
#chat .mes:not([is_user="true"]) .mes_block::before{content:var(--yy-brush);position:absolute;left:182px;top:40px;writing-mode:vertical-rl;
  font:52px/.95 var(--yy-brushf);color:var(--yy-pale);pointer-events:none;
  -webkit-mask-image:linear-gradient(#000 50%,transparent 92%),radial-gradient(circle,#000 1.1px,transparent 1.5px);-webkit-mask-size:100% 100%,4px 4px;-webkit-mask-composite:source-over;
  mask-image:linear-gradient(#000 50%,transparent 92%),radial-gradient(circle,#000 1.1px,transparent 1.5px);mask-size:100% 100%,4px 4px;mask-composite:add}
#chat .mes:not([is_user="true"]) .ch_name{position:absolute;left:240px;right:10px;top:46px}
#chat .mes:not([is_user="true"]) .ch_name .flex-container{flex-wrap:wrap}
#chat .mes:not([is_user="true"]) .ch_name .name_text{font:italic 30px/1.1 var(--yy-fell);font-synthesis:none;color:var(--yy-pale);letter-spacing:.02em;white-space:normal;overflow-wrap:anywhere}
#chat .mes:not([is_user="true"]) .ch_name .timestamp{display:block;width:100%;font-size:10px;line-height:1.6;margin-top:4px;white-space:normal}
#chat .mes:not([is_user="true"]) .ch_name::after{content:var(--yy-vitals);display:block;white-space:pre;margin-top:12px;
  font:11px/2.1 var(--yy-dot);letter-spacing:.12em;color:#9a9ca3}
#chat .mes:not([is_user="true"]) .mes_text>p:first-child::first-letter{font-family:var(--yy-brushf);font-size:2.9em;float:left;line-height:1;margin:.1em .18em 0 0;color:#e2ddd0}
#chat .mes:not([is_user="true"]) .mes_block::after{content:var(--yy-sign);display:flex;justify-content:flex-end;align-items:flex-end;
  height:84px;padding:0 84px 16px 0;margin-top:4px;background:var(--yy-lily) right bottom/84px 84px no-repeat;
  font:11px var(--yy-dot);letter-spacing:.2em;color:var(--yy-dim)}

/* —— 用户楼：守夜人 —— */
#chat .mes[is_user="true"]{display:flex;flex-direction:row-reverse;align-items:flex-start;background:none;box-shadow:none;padding:0}
#chat .mes[is_user="true"] .mesAvatarWrapper{position:relative;flex:none;width:140px;height:140px;margin:0 0 0 -52px;padding:0;z-index:3}
#chat .mes[is_user="true"] .mes_block{flex:1;min-width:0;margin-top:40px;padding:14px 64px 16px 16px;
  background-color:var(--yy-plate);background-image:var(--yy-vignette),var(--yy-grain);box-shadow:var(--yy-plate-shadow)}
#chat .mes[is_user="true"] .ch_name .name_text{font:12px var(--yy-dot);letter-spacing:.3em;color:var(--yy-dim)}
#chat .mes[is_user="true"] .mes_text{color:#d4d3ce}

/* ═══ 头像与消散 ═══ */
#chat .mes .mesAvatarWrapper>:not(.avatar){position:absolute;left:0;right:0;top:calc(100% + 8px);text-align:center;font:11px var(--yy-dot);color:var(--yy-dim)}
#chat .mes .mesAvatarWrapper .tokenCounterDisplay{top:calc(100% + 24px)}
#chat .mes .mesAvatarWrapper .avatar{position:relative;width:100%;height:100%;margin:0;border:0;box-shadow:none;background:none}
#chat .mes .avatar img{display:block;width:100%;height:100%;border-radius:50%;object-fit:cover;border:0;box-shadow:none;
  -webkit-mask:var(--yy-ramp) 0% 100%/300% 300% no-repeat;mask:var(--yy-ramp) 0% 100%/300% 300% no-repeat;
  animation:none}
#chat .mes[is_user="true"] .avatar img{position:absolute;left:24%;top:24%;width:52%;height:52%}
/* 碎裂前沿的砂砾 */
#chat .mes .avatar::after{content:"";position:absolute;inset:0;border-radius:50%;pointer-events:none;background:var(--yy-edge);z-index:2;
  -webkit-mask:var(--yy-ramp) 0% 100%/300% 300% no-repeat,var(--yy-ramp) 0% 100%/300% 300% no-repeat;-webkit-mask-composite:xor;
  mask:var(--yy-ramp) 0% 100%/300% 300% no-repeat,var(--yy-ramp) 0% 100%/300% 300% no-repeat;mask-composite:exclude;
  animation:none}
#chat .mes[is_user="true"] .avatar::after{inset:24%}
/* 角色：舷窗的霜 ／ 用户：星尘环 */
#chat .mes:not([is_user="true"]) .avatar::before{content:"";position:absolute;inset:0;z-index:3;pointer-events:none;background:var(--yy-frost) center/100% 100% no-repeat}
#chat .mes[is_user="true"] .avatar::before{content:"";position:absolute;inset:0;z-index:3;pointer-events:none;background:var(--yy-frame) center/100% 100% no-repeat}
/* 飘走的星尘（斜向右上的烟柱） */
#chat .mes .mesAvatarWrapper::before{content:"";position:absolute;left:50%;bottom:50%;width:140%;height:210%;margin-left:-70%;
  transform-origin:50% 100%;transform:rotate(45deg);pointer-events:none;z-index:4;opacity:0;
  background:var(--yy-fine),var(--yy-coarse);
  -webkit-mask:linear-gradient(to top,#000 20%,transparent 96%),radial-gradient(ellipse 50% 100% at 50% 100%,#000 25%,transparent 100%);-webkit-mask-composite:source-in;
  mask:linear-gradient(to top,#000 20%,transparent 96%),radial-gradient(ellipse 50% 100% at 50% 100%,#000 25%,transparent 100%);mask-composite:intersect;
  animation:none}
/* 舱底生命灯 */
#chat .mes:not([is_user="true"]) .mesAvatarWrapper::after{content:"";position:absolute;left:50%;bottom:-4px;width:7px;height:7px;margin-left:-3.5px;border-radius:50%;
  background:var(--yy-am);z-index:5;opacity:.6}
#chat .mes:not([is_user="true"]) .mesAvatarWrapper>:not(.avatar){top:calc(100% + 12px)}

/* 只让最新的两层楼动起来，往上翻的旧楼保持静止，省性能 */
#chat .mes:nth-last-child(-n+2) .avatar img{animation:yy-dis var(--yy-dz-speed) linear infinite;animation-play-state:var(--yy-dz-state);will-change:mask-position}
#chat .mes:nth-last-child(-n+2) .avatar::after{animation:yy-edg var(--yy-dz-speed) linear infinite;animation-play-state:var(--yy-dz-state)}
#chat .mes:nth-last-child(-n+2) .mesAvatarWrapper::before{animation:yy-spr var(--yy-dz-speed) ease-in-out infinite;animation-play-state:var(--yy-dz-state)}
#chat .mes:nth-last-child(-n+2):not([is_user="true"]) .mesAvatarWrapper::after{animation:yy-br 5s ease-in-out infinite}
@keyframes yy-br{0%,100%{opacity:.3}50%{opacity:1}}
@keyframes yy-dis{0%,10%{-webkit-mask-position:0% 100%;mask-position:0% 100%}58%,68%{-webkit-mask-position:100% 0%;mask-position:100% 0%}96%,100%{-webkit-mask-position:0% 100%;mask-position:0% 100%}}
@keyframes yy-edg{0%,10%{-webkit-mask-position:0% 100%,0% 100%;mask-position:0% 100%,0% 100%}15%{-webkit-mask-position:10.4% 89.6%,0% 100%;mask-position:10.4% 89.6%,0% 100%}58%{-webkit-mask-position:100% 0%,89.6% 10.4%;mask-position:100% 0%,89.6% 10.4%}63%,68%{-webkit-mask-position:100% 0%,100% 0%;mask-position:100% 0%,100% 0%}73%{-webkit-mask-position:82.1% 17.9%,100% 0%;mask-position:82.1% 17.9%,100% 0%}96%{-webkit-mask-position:0% 100%,14.8% 85.2%;mask-position:0% 100%,14.8% 85.2%}100%{-webkit-mask-position:0% 100%,0% 100%;mask-position:0% 100%,0% 100%}}
@keyframes yy-spr{0%,12%{opacity:0;background-position:0 0,0 0}28%{opacity:1}60%{opacity:.9;background-position:0 -300px,0 -150px}68%{opacity:.55;background-position:0 -330px,0 -165px}86%{opacity:.85;background-position:0 -80px,0 -40px}97%,100%{opacity:0;background-position:0 0,0 0}}

/* ═══ 消息操作图标 ═══ */
#chat .mes .mes_buttons .mes_button,#chat .mes .mes_buttons .extraMesButtons>div{color:#9a9ca3}
#chat .mes .mes_buttons .mes_edit,#chat .mes .mes_buttons .extraMesButtonsHint{color:transparent;width:22px;height:22px;background:center/16px 16px no-repeat}
#chat .mes .mes_buttons .mes_edit::before,#chat .mes .mes_buttons .extraMesButtonsHint::before{content:""}
#chat .mes .mes_buttons .mes_edit{background-image:var(--yy-i-quill)}
#chat .mes .mes_buttons .extraMesButtonsHint{background-image:var(--yy-i-star)}
#chat .mes .timestamp,#chat .mes .mesIDDisplay,#chat .mes .mes_timer{font-family:var(--yy-dot);font-size:11px;letter-spacing:.1em;color:var(--yy-dim)}

/* ═══ 输入区 ═══ */
#send_form{background-color:var(--yy-plate);background-image:var(--yy-vignette),var(--yy-grain);border:0;border-radius:0;box-shadow:var(--yy-plate-shadow)}
#send_textarea{font-family:var(--yy-serif);color:var(--yy-ink);background-color:transparent}
#send_but{width:32px;height:32px;min-width:32px;color:transparent;background:var(--yy-send) center/32px 32px no-repeat;box-shadow:none;border:0;margin:0 2px;transition:transform .6s}
#send_but:hover{transform:rotate(-30deg)}
#send_but::before{content:""}
#options_button,#extensionsMenuButton{color:transparent;width:24px;height:24px;background:center/18px 18px no-repeat;opacity:.75}
#options_button::before,#extensionsMenuButton::before{content:""}
#options_button{background-image:var(--yy-i-moon)}
#extensionsMenuButton{background-image:var(--yy-i-puzzle)}

/* ═══ 占位文字（换成本主题的话） ═══ */
input::placeholder,textarea::placeholder,#send_textarea::placeholder,#send_form textarea::placeholder,
.text_pole::placeholder,textarea.text_pole::placeholder{color:transparent;opacity:0}
textarea:placeholder-shown,input[type="text"]:placeholder-shown,input[type="search"]:placeholder-shown,input:not([type]):placeholder-shown{
  background-image:url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22420%22%20height%3D%2222%22%3E%3Ctext%20x%3D%220%22%20y%3D%2216%22%20font-family%3D%22Noto%20Serif%20SC%2CSongti%20SC%2Cserif%22%20font-size%3D%2213.5%22%20fill%3D%22%236c6e75%22%20letter-spacing%3D%221%22%3E%E5%9C%A8%E5%86%BB%E5%9C%9F%E9%87%8C%E6%89%BE%E4%B8%80%E9%A2%97%E6%98%9F%E2%80%A6%E2%80%A6%3C%2Ftext%3E%3C%2Fsvg%3E");background-repeat:no-repeat;background-origin:content-box;background-position:0 50%}
textarea:placeholder-shown{background-position:0 2px}
#send_textarea:placeholder-shown{background-image:url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22420%22%20height%3D%2222%22%3E%3Ctext%20x%3D%220%22%20y%3D%2216%22%20font-family%3D%22Noto%20Serif%20SC%2CSongti%20SC%2Cserif%22%20font-size%3D%2213.5%22%20fill%3D%22%236c6e75%22%20letter-spacing%3D%221%22%3E%E9%9A%94%E7%9D%80%E8%88%B1%E5%A3%81%E8%AF%B4%E5%90%A7%EF%BC%8C%E4%BB%96%E5%90%AC%E5%BE%97%E8%A7%81%E2%80%A6%E2%80%A6%3C%2Ftext%3E%3C%2Fsvg%3E");background-position:0 50%}
#character_search_bar:placeholder-shown{background-image:url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22420%22%20height%3D%2222%22%3E%3Ctext%20x%3D%220%22%20y%3D%2216%22%20font-family%3D%22Noto%20Serif%20SC%2CSongti%20SC%2Cserif%22%20font-size%3D%2213.5%22%20fill%3D%22%236c6e75%22%20letter-spacing%3D%221%22%3E%E7%BF%BB%E6%89%BE%E5%85%B6%E4%BB%96%E4%BC%91%E7%9C%A0%E8%88%B1%E2%80%A6%E2%80%A6%3C%2Ftext%3E%3C%2Fsvg%3E")}
#world_info_search:placeholder-shown{background-image:url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22420%22%20height%3D%2222%22%3E%3Ctext%20x%3D%220%22%20y%3D%2216%22%20font-family%3D%22Noto%20Serif%20SC%2CSongti%20SC%2Cserif%22%20font-size%3D%2213.5%22%20fill%3D%22%236c6e75%22%20letter-spacing%3D%221%22%3E%E5%9C%A8%E6%98%9F%E5%9B%BE%E9%87%8C%E6%A3%80%E7%B4%A2%E2%80%A6%E2%80%A6%3C%2Ftext%3E%3C%2Fsvg%3E")}
#completion_prompt_manager_popup_entry_form_prompt:placeholder-shown{background-image:url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22420%22%20height%3D%2222%22%3E%3Ctext%20x%3D%220%22%20y%3D%2216%22%20font-family%3D%22Noto%20Serif%20SC%2CSongti%20SC%2Cserif%22%20font-size%3D%2213.5%22%20fill%3D%22%236c6e75%22%20letter-spacing%3D%221%22%3E%E6%8A%8A%E8%A6%81%E4%BB%96%E6%A2%A6%E8%A7%81%E7%9A%84%E5%86%99%E5%9C%A8%E8%BF%99%E9%87%8C%E2%80%A6%E2%80%A6%3C%2Ftext%3E%3C%2Fsvg%3E")}

/* ═══ 输入框 / 下拉 ═══ */
.text_pole,textarea.text_pole,select{background-color:var(--yy-well);border:0;border-radius:0;color:var(--yy-ink);
  box-shadow:inset 0 2px 8px rgba(0,0,0,.8),inset 0 0 0 1px rgba(255,255,255,.06)}

/* ═══ 按钮 ═══ */
.menu_button{background-color:#121317;border:0;border-radius:0;color:#e6e2d7;letter-spacing:.08em;
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.05),inset 0 0 20px rgba(0,0,0,.8);filter:none}
.menu_button:hover{background-color:#17181d;box-shadow:inset 0 0 0 1.5px rgba(217,163,90,.55),inset 0 0 20px rgba(0,0,0,.8)}
.popup .popup-controls .popup-button-ok,.menu_button.menu_button_active{background-color:var(--yy-am);color:#1a1208;box-shadow:none}

/* ═══ 复选框：日食环 ═══ */
input[type='checkbox']:not(#nav-toggle):not(#rm_button_panel_pin):not(#lm_button_panel_pin):not(#WI_panel_pin){
  -webkit-appearance:none;appearance:none;width:18px;height:18px;min-width:18px;border:0;border-radius:50%;margin:0 6px 0 0;cursor:pointer;flex:none;
  background:radial-gradient(circle,#000 0 52%,transparent 55%),radial-gradient(circle,rgba(220,220,225,.9) .7px,transparent 1px) 0 0/3px 3px;box-shadow:none;filter:none;opacity:1}
input[type='checkbox']:not(#nav-toggle):not(#rm_button_panel_pin):not(#lm_button_panel_pin):not(#WI_panel_pin):checked{
  background:var(--yy-moon-on) center/100% 100% no-repeat}
input[type='checkbox']:not(#nav-toggle):not(#rm_button_panel_pin):not(#lm_button_panel_pin):not(#WI_panel_pin)::before,
input[type='checkbox']:not(#nav-toggle):not(#rm_button_panel_pin):not(#lm_button_panel_pin):not(#WI_panel_pin)::after{display:none}

/* ═══ 滑块：点阵轨道 ═══ */
input[type='range']{-webkit-appearance:none;appearance:none;background:transparent;height:18px}
input[type='range']::-webkit-slider-runnable-track{height:2px;background:radial-gradient(circle,rgba(200,200,205,.7) .8px,transparent 1.1px) 0 0/4px 2px;border:0}
input[type='range']::-webkit-slider-thumb{-webkit-appearance:none;width:18px;height:18px;margin-top:-8px;border-radius:50%;background:#0b0c0e var(--yy-moon-on) center/100% 100% no-repeat;box-shadow:none;border:0}
input[type='range']::-moz-range-track{height:2px;background:radial-gradient(circle,rgba(200,200,205,.7) .8px,transparent 1.1px) 0 0/4px 2px;border:0}
input[type='range']::-moz-range-thumb{width:18px;height:18px;border-radius:50%;background:#0b0c0e var(--yy-moon-on) center/100% 100% no-repeat;box-shadow:none;border:0}

/* ═══ 标题条：扩展抽屉头 / 设置小标题 ═══ */
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
.standoutHeader,#user-settings-block h4{
  position:relative;border:0;border-radius:0;margin-bottom:6px;padding:10px 12px;color:#e6e3da;letter-spacing:.15em;
  background-color:rgba(10,11,14,.92);background-image:linear-gradient(90deg,rgba(10,11,14,.95) 25%,rgba(10,11,14,.5)),var(--yy-nebula);
  background-size:auto,240% auto;background-position:0 0,70% 50%;background-repeat:no-repeat;box-shadow:inset 0 0 30px rgba(0,0,0,.9)}
#extensions_settings .inline-drawer-toggle.inline-drawer-header:hover,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover,
.standoutHeader:hover,#user-settings-block h4:hover{
  background-color:rgba(22,20,16,.95);background-image:linear-gradient(90deg,rgba(22,20,16,.95) 25%,rgba(22,20,16,.45)),var(--yy-nebula);
  box-shadow:inset 0 0 0 1.5px rgba(217,163,90,.5),inset 0 0 30px rgba(0,0,0,.9)}
.inline-drawer-header .inline-drawer-icon{color:transparent;width:16px;height:16px;background:var(--yy-i-star) center/contain no-repeat;transition:transform .3s}
.inline-drawer-header .inline-drawer-icon::before{content:""}
.inline-drawer-header .inline-drawer-icon.up{transform:rotate(45deg)}

/* ═══ 预设条目：满月＝醒着 ／ 空环＝沉睡 ═══ */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt{border:0;border-radius:0;background:transparent}
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:nth-child(even){background:rgba(255,255,255,.025)}
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled{border:0;outline:0;box-shadow:none}
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name *{
  opacity:1 !important;filter:none !important}
/* 行内小图标：开没开都一样亮，统一成冷灰，不用默认的红色 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt .fa-solid{color:#9a9ca3;opacity:.85 !important;filter:none !important}
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt .fa-solid:hover{color:#e6e2d7;opacity:1 !important}
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt .prompt-manager-toggle-action,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt .prompt-manager-edit-action{color:transparent;opacity:1 !important}
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name *{
  color:var(--SmartThemeBodyColor) !important}
#completion_prompt_manager .prompt-manager-toggle-action{color:transparent;width:18px;height:18px;border-radius:50%;display:inline-block;vertical-align:middle;flex:none}
#completion_prompt_manager .prompt-manager-toggle-action::before{content:""}
#completion_prompt_manager .prompt-manager-toggle-action.fa-toggle-on{background:var(--yy-moon-on) center/100% 100% no-repeat;box-shadow:none}
#completion_prompt_manager .prompt-manager-toggle-action.fa-toggle-off{background:radial-gradient(circle,rgba(220,220,225,.85) .7px,transparent 1px) 0 0/3px 3px;
  -webkit-mask:radial-gradient(circle,transparent 0 55%,#000 58%);mask:radial-gradient(circle,transparent 0 55%,#000 58%)}
#completion_prompt_manager .prompt-manager-edit-action{color:transparent;width:20px;min-width:20px;height:20px;font-size:inherit;display:inline-block;background:var(--yy-i-quill) center/17px 17px no-repeat}
#completion_prompt_manager .prompt-manager-edit-action::before{content:""}
#completion_prompt_manager .prompt_manager_prompt_tokens,#completion_prompt_manager .completion_prompt_manager_prompt_tokens{font-family:var(--yy-dot);font-size:11px;letter-spacing:.1em;color:#777a82}

/* —— 小铅笔弹窗 —— */
#completion_prompt_manager_popup{position:relative;background-color:var(--yy-plate);background-image:var(--yy-vignette),var(--yy-grain);border:0;border-radius:0;box-shadow:var(--yy-plate-shadow)}
#completion_prompt_manager_popup::before{content:"";position:absolute;right:-20px;top:-24px;width:130px;height:130px;pointer-events:none;opacity:.5;background:var(--yy-lily) center/contain no-repeat}
#completion_prompt_manager_popup input,#completion_prompt_manager_popup textarea,#completion_prompt_manager_popup select,#completion_prompt_manager_popup label{opacity:1;filter:none}

/* ═══ 通用弹窗 ═══ */
.popup{background-color:#0e0f12;background-image:var(--yy-vignette),var(--yy-grain);border:0;border-radius:0;box-shadow:var(--yy-plate-shadow),0 20px 60px rgba(0,0,0,.7)}

/* ═══ 思考过程折叠块 ═══ */
#chat .mes .mes_reasoning_details{background-color:var(--yy-well);border:0;border-radius:0;box-shadow:inset 0 2px 10px rgba(0,0,0,.85),inset 0 0 0 1px rgba(255,255,255,.05);color:var(--yy-dim)}
#chat .mes .mes_reasoning_details .mes_reasoning_summary,#chat .mes .mes_reasoning_details summary{background:transparent;border:0;border-radius:0;color:#9a9ca3;font-family:var(--yy-dot);font-size:12px;letter-spacing:.2em}
#chat .mes .mes_reasoning{color:#8a8b91;font-size:.92em}

